-- chair-step: inverse of read_lane_v2_b3_60_workflow_definition — un-enrolls workflow.definition from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'workflow' and table_name = 'definition' and is_active);
select iam.apply_rls('workflow', 'definition', (select token from platform.entity_types where schema_name = 'workflow' and table_name = 'definition' and is_active), (select rls_variant from platform.entity_types where schema_name = 'workflow' and table_name = 'definition' and is_active));
